def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def admit_sources(sources):
    """Exact postimage/inverse admission, never a native callback/state model."""
    from terminal_awt240_source_projection import text_before_terminal_awt240
    sources = {rel: text_before_terminal_awt240(rel, text) for rel, text in sources.items()}
    expected = set(_SPEC["changed_paths"]) | set(_SPEC["new_paths"]) | set(_SPEC["support_sha256"])
    if set(sources) != expected:
        raise ValueError("Exact failed Share observation source/support set required")
    reconstructed = {}
    for rel in (*_SPEC["changed_paths"], *_SPEC["new_paths"]):
        if digest(sources[rel]) != _SPEC["postimage_sha256"][rel]:
            raise ValueError("Exact failed Share observation postimage required")
        if rel in _SPEC["changed_paths"]:
            text = sources[rel]
            for fragment in reversed(_SPEC["fragments"][rel]):
                if (digest(fragment["before"]) != fragment["before_fragment_sha256"] or
                        digest(fragment["after"]) != fragment["after_fragment_sha256"] or
                        text.count(fragment["after"]) != 1):
                    raise ValueError("Exact unique failed Share observation inverse required")
                text = text.replace(fragment["after"], fragment["before"], 1)
            if digest(text) != _SPEC["preimage_sha256"][rel]:
                raise ValueError("Observation inverse changed original native/guard/route bytes")
            reconstructed[rel] = text
    for rel, value in _SPEC["support_sha256"].items():
        if digest(sources[rel]) != value:
            raise ValueError("Original production and thirteen native body bytes must stay unchanged")
    for rel, methods in _SPEC["native_identity"].items():
        if re.findall(r"@Test\s+fun\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(\s*\)", sources[rel]) != methods:
            raise ValueError("Exact original thirteen declarations required")
    return reconstructed


class IosShareTerminalFailureObservationNewOnlyTests(unittest.TestCase):
    def setUp(self):
        paths = set(_SPEC["changed_paths"]) | set(_SPEC["new_paths"]) | set(_SPEC["support_sha256"])
        self.sources = {rel: (ROOT / rel).read_text() for rel in paths}
        self.before = admit_sources(self.sources)

    def plan(self, root=ROOT, **kwargs):
        return lt.plan(root, "ios", only_modules=("calf-share",), focus=FOCUS, **kwargs)

    def refuse_mutation(self, relative, before, after):
        self.assertEqual(1, self.sources[relative].count(before))
        changed = dict(self.sources)
        changed[relative] = changed[relative].replace(before, after, 1)
        with self.assertRaises(ValueError):
            admit_sources(changed)

    def test_exact_images_invert_to_original_sources_and_all13_bodies_production_and_guard_methods_stay_held(self):
        self.assertEqual(13, sum(map(len, _SPEC["native_identity"].values())))
        self.assertNotIn("calf-share/src/iosMain/kotlin/com/mohamedrejeb/calf/share/ShareLauncher.ios.kt", _SPEC["changed_paths"])
        for relative in _SPEC["changed_paths"]:
            self.assertEqual(_SPEC["preimage_sha256"][relative], digest(self.before[relative]))
        for relative in ("scripts/ci/test_ios_share_owned_root_barriers.py",
                         "scripts/ci/test_share_settings_fixture_recovery.py",
                         "scripts/ci/test_ui_alert_important_recovery.py"):
            def method_nodes(text):
                return {node.name: ast.dump(node, include_attributes=False)
                        for parent in ast.parse(text).body if isinstance(parent, ast.ClassDef)
                        for node in parent.body if isinstance(node, ast.FunctionDef) and node.name.startswith("test_")}
            self.assertEqual(method_nodes(self.before[relative]), method_nodes(self.sources[relative]))
        self.refuse_mutation(NATIVE, "(1..index + 1).map { it to ShareOutcome.Completed }, deliveries)", "(1..index + 1).map { it to ShareOutcome.Dismissed }, deliveries)")

