    def test_missing_disabled_injected_helper_removed_native_extra_plan_or_foreign_suite_refuses(self):
        plan = self.plan()
        for key, value in (("required_testcases", []), ("test_filter", "*"), ("task", ":calf-share:publish"),
                           ("project", ":calf-ui"), ("report_directory", "wrong"), ("native_test_host", "sample")):
            changed = copy.deepcopy(plan)
            changed["expected"][0][key] = value
            with self.subTest(field=key), self.assertRaises(ValueError):
                lt.validate_test_focus(changed)
        for relative in (*lt.IOS_SHARE_APPLICATION_SOURCES, HELPER):
            changed = copy.deepcopy(plan)
            changed["expected"][0]["test_source_files"].remove(relative)
            with self.subTest(missing=relative), self.assertRaises(ValueError):
                lt.validate_test_focus(changed)
        for suite, modules in (("desktop", ("calf-share",)), ("js", ("calf-share",)), ("wasm", ("calf-share",)),
                               ("ios", ("calf-ui",)), ("ios", ("calf-file-picker",)), ("ios", None)):
            with self.subTest(suite=suite, modules=modules), self.assertRaises(ValueError):
                lt.plan(ROOT, suite, only_modules=modules, focus=FOCUS)
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            (root / "settings.gradle.kts").write_text('include(\n    ":calf-share",\n)\n')
            (root / "calf-share").mkdir()
            (root / "calf-share/build.gradle.kts").write_text("// Synthetic source-only module\n")
            for relative in (*lt.IOS_SHARE_APPLICATION_SOURCES, *tuple(_SPEC["native_identity"]), HELPER):
                target = root / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(self.sources.get(relative, (ROOT / relative).read_text()))
            def local_plan():
                return self.plan(root, minimum_modules=("calf-share",))
            self.assertEqual(1, len(local_plan()["expected"][0]["required_testcases"]))
            native = root / NATIVE
            original = native.read_text()
            native.write_text(original.replace("@Test fun ", "@Ignore\n    @Test fun ", 1))
            with self.assertRaises(ValueError): local_plan()
            native.write_text(original.replace("@Test fun " + METHOD, "fun " + METHOD, 1))
            with self.assertRaises(ValueError): local_plan()
            native.write_text(original)
            helper = root / HELPER
            helper.write_text(self.sources[HELPER] + "\n@Test fun injectedNativeScenario() {}\n")
            with self.assertRaises(ValueError): local_plan()
            helper.write_text(self.sources[HELPER] + "\n@Ignore class DisabledObservation\n")
            with self.assertRaises(ValueError): local_plan()
            helper.unlink()
            with self.assertRaises(ValueError): local_plan()

